import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int64_t stride,
                                          int64_t padding,
                                          int64_t output_padding,
                                          int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Single fused ConvTranspose3d kernel for the common case used by Model:
//   stride=1, dilation=1, groups=1, square kernel KxKxK.
// Cooperative tiled kernel:
//   block = one batch n, one output-channel tile (4), one 8x8x8 output-spatial tile.
//   For each input channel, the needed input halo is staged in shared memory and
//   reused across all 4 output channels in the tile.
template <typename T>
__global__ void conv_transpose3d_s1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int K, int pad,
    int td, int th, int tw,
    int halo, int pipe,
    int sXn, int sXc, int sXd, int sXh,
    int sYn, int sYc, int sYd, int sYh,
    int sWi, int sWo, int sWd, int sWh)
{
  constexpr int Threads  = 128;
  constexpr int Tile     = 8;
  constexpr int PVec     = 4;    // Tile^3 / Threads = 512 / 128 (4 spatial outputs per thread)
  constexpr int CoTile   = 4;

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int co_base = blockIdx.y * CoTile;

  const int tile_id = blockIdx.x;
  const int tiles_hw = th * tw;
  const int od_t = tile_id / tiles_hw;
  const int rem  = tile_id - od_t * tiles_hw;
  const int oh_t = rem / tw;
  const int ow_t = rem - oh_t * tw;

  const int od_base = od_t * Tile;
  const int oh_base = oh_t * Tile;
  const int ow_base = ow_t * Tile;

  const int halo2 = halo * halo;
  const int halo3 = halo2 * halo;
  const int k2 = K * K;
  const int k3 = k2 * K;

  extern __shared__ float smem_raw[];
  // Double-buffered shared memory for pipelined staged loads: while the
  // buffer for input channel ci is consumed by compute, the alternate
  // buffer is asynchronously staged (cp.async) for channel ci+1.
  float* sS_buf0 = smem_raw;
  float* sS_buf1 = pipe ? (smem_raw + halo3) : smem_raw;
  float* sW_buf0 = smem_raw + (pipe ? 2 : 1) * halo3;
  float* sW_buf1 = pipe ? (sW_buf0 + CoTile * k3) : sW_buf0;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, K, K, K),
      make_stride(sWi, sWo, sWd, sWh, Int<1>{})
  );

  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(Cout),
      make_stride(Int<1>{})
  );

  const int in_od_origin = od_base + pad - (K - 1);
  const int in_oh_origin = oh_base + pad - (K - 1);
  const int in_ow_origin = ow_base + pad - (K - 1);

  int off[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    const int p = tid + i * Threads;  // [0, 512), Tile=8 so decode is shifts
    const int z = p >> 6;
    const int r = p & 63;
    const int y = r >> 3;
    const int x = r & 7;
    off[i] = z * halo2 + y * halo + x;
  }
  float acc[CoTile][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (B != nullptr && co < Cout) {
      bval = (float)mB(co);
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }
  // Pipelined staged loads: cp.async double-buffering overlaps the
  // global-memory staging of input channel ci+1 (input halo + weights)
  // with the compute of channel ci, hiding gmem latency behind FMA work.
  auto stage_channel = [&](int ci, float* sS, float* sW) {
    for (int idx = tid; idx < halo3; idx += Threads) {
      const int hd = idx / halo2;
      const int r  = idx - hd * halo2;
      const int hh = r / halo;
      const int hw = r - hh * halo;
      const int id = in_od_origin + hd;
      const int ih = in_oh_origin + hh;
      const int iw = in_ow_origin + hw;
      const bool valid = ((unsigned)id < (unsigned)Din &&
                          (unsigned)ih < (unsigned)Hin &&
                          (unsigned)iw < (unsigned)Win);
      const float* src = &mX(ci, valid ? id : 0, valid ? ih : 0, valid ? iw : 0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
      const unsigned dst = (unsigned)__cvta_generic_to_shared(sS + idx);
      const int sz = valid ? 4 : 0;  // src-size 0 => zero-fill (padding)
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" :: "r"(dst), "l"(src), "r"(sz));
#else
      sS[idx] = valid ? *src : 0.0f;
#endif
    }
    const int w_items = CoTile * k3;
    for (int idx = tid; idx < w_items; idx += Threads) {
      const int cc = idx / k3;
      const int kk = idx - cc * k3;
      const int kd = kk / k2;
      const int rr = kk - kd * k2;
      const int kh = rr / K;
      const int kw = rr - kh * K;
      const int co = co_base + cc;
      const bool valid = (co < Cout);
      const float* src = &mW(ci, valid ? co : 0, kd, kh, kw);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
      const unsigned dst = (unsigned)__cvta_generic_to_shared(sW + idx);
      const int sz = valid ? 4 : 0;
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" :: "r"(dst), "l"(src), "r"(sz));
#else
      sW[idx] = valid ? *src : 0.0f;
#endif
    }
  };
  auto compute_tile = [&](const float* sS, const float* sW) {
    for (int kd = 0; kd < K; ++kd) {
      const int kdr = K - 1 - kd;
      for (int kh = 0; kh < K; ++kh) {
        const int khr = K - 1 - kh;
        for (int kw = 0; kw < K; ++kw) {
          const int kwr = K - 1 - kw;
          const int kk = (kd * K + kh) * K + kw;
          const int tap = kdr * halo2 + khr * halo + kwr;
          float wv[CoTile];
          #pragma unroll
          for (int cc = 0; cc < CoTile; ++cc) {
            wv[cc] = sW[cc * k3 + kk];
          }
          float xvv[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xvv[i] = sS[off[i] + tap];
          }
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            #pragma unroll
            for (int cc = 0; cc < CoTile; ++cc) {
              acc[cc][i] += xvv[i] * wv[cc];
            }
          }
        }
      }
    }
  };
  if (pipe) {
    // Prologue: asynchronously stage channel 0 into buffer 0.
    stage_channel(0, sS_buf0, sW_buf0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;\n" ::);
#endif
    for (int ci = 0; ci < Cin; ++ci) {
      // Prefetch channel ci+1 into the alternate buffer while computing ci.
      if (ci + 1 < Cin) {
        stage_channel(ci + 1, ((ci + 1) & 1) ? sS_buf1 : sS_buf0,
                            ((ci + 1) & 1) ? sW_buf1 : sW_buf0);
      }
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
      asm volatile("cp.async.commit_group;\n" ::);
      asm volatile("cp.async.wait_group 1;\n" ::);  // current buffer ready
#endif
      __syncthreads();
      compute_tile((ci & 1) ? sS_buf1 : sS_buf0, (ci & 1) ? sW_buf1 : sW_buf0);
      __syncthreads();  // all reads done before this buffer is re-staged
    }
  } else {
    // Fallback (large K): single-buffered staging, same semantics.
    for (int ci = 0; ci < Cin; ++ci) {
      stage_channel(ci, sS_buf0, sW_buf0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
      asm volatile("cp.async.commit_group;\n" ::);
      asm volatile("cp.async.wait_group 0;\n" ::);
#endif
      __syncthreads();
      compute_tile(sS_buf0, sW_buf0);
      __syncthreads();
    }
  }
  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      const int p = tid + i * Threads;
      const int z = p >> 6;
      const int r = p & 63;
      const int y = r >> 3;
      const int x = r & 7;
      const int od = od_base + z;
      const int oh = oh_base + y;
      const int ow = ow_base + x;
      if (od < Dout && oh < Hout && ow < Wout) {
        mY(co, od, oh, ow) = static_cast<T>(acc[cc][i]);
      }
    }
  }
}

torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int64_t stride,
                                          int64_t padding,
                                          int64_t output_padding,
                                          int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, Din, Hin, Win]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout, K, K, K] for groups=1 ConvTranspose3d");
  TORCH_CHECK(stride == 1, "custom CUTE kernel supports stride=1");
  TORCH_CHECK(groups == 1, "custom CUTE kernel supports groups=1");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(output_padding == 0, "custom CUTE kernel supports output_padding=0");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N   = x_c.size(0);
  const int64_t Cin = x_c.size(1);
  const int64_t Din = x_c.size(2);
  const int64_t Hin = x_c.size(3);
  const int64_t Win = x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
  const int64_t Cout = w_c.size(1);
  const int64_t Kd = w_c.size(2);
  const int64_t Kh = w_c.size(3);
  const int64_t Kw = w_c.size(4);
  TORCH_CHECK(Kd == Kh && Kh == Kw, "kernel must be square/cubic");
  const int64_t K = Kd;
  TORCH_CHECK(K >= 1 && K <= 15, "kernel size supported range is [1, 15]");

  const int64_t Dout = (Din - 1) - 2 * padding + K + output_padding;
  const int64_t Hout = (Hin - 1) - 2 * padding + K + output_padding;
  const int64_t Wout = (Win - 1) - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed-conv output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x_c.options());

  constexpr int Threads = 128;
  constexpr int Tile = 8;
  constexpr int CoTile = 4;

  const int64_t halo = Tile + K - 1;
  const int64_t halo3 = halo * halo * halo;
  const int64_t k3 = K * K * K;
  const int64_t smem_single = (halo3 + CoTile * k3) * (int64_t)sizeof(float);
  TORCH_CHECK(smem_single <= 96 * 1024, "required dynamic shared memory is too large");
  // Enable double-buffered pipelined staging only when the extra halo
  // buffer still fits in shared memory; otherwise use single buffering.
  const int pipe = ((2 * halo3 + CoTile * k3) * (int64_t)sizeof(float) <= 96 * 1024) ? 1 : 0;
  const int64_t smem_bytes = pipe ? (2 * halo3 + CoTile * k3) * (int64_t)sizeof(float) : smem_single;

  const int64_t td = (Dout + Tile - 1) / Tile;
  const int64_t th = (Hout + Tile - 1) / Tile;
  const int64_t tw = (Wout + Tile - 1) / Tile;
  const int64_t sp_tiles = td * th * tw;
  const int64_t co_tiles = (Cout + CoTile - 1) / CoTile;

  TORCH_CHECK(sp_tiles <= INT32_MAX, "too many spatial tiles");
  TORCH_CHECK(co_tiles <= 65535, "too many output-channel tiles");
  TORCH_CHECK(N <= 65535, "batch too large for this simple grid mapping");

  dim3 block(Threads);
  dim3 grid((unsigned)sp_tiles, (unsigned)co_tiles, (unsigned)N);

  TORCH_CHECK(Cin * Din * Hin * Win <= INT32_MAX &&
              Cout * Dout * Hout * Wout <= INT32_MAX &&
              Cout * Kd * Kh * Kw <= INT32_MAX,
              "tensor too large for int32-indexed custom kernel");
  const int sXn = (int)(Cin * Din * Hin * Win);
  const int sXc = (int)(Din * Hin * Win);
  const int sXd = (int)(Hin * Win);
  const int sXh = (int)Win;
  const int sYn = (int)(Cout * Dout * Hout * Wout);
  const int sYc = (int)(Dout * Hout * Wout);
  const int sYd = (int)(Hout * Wout);
  const int sYh = (int)Wout;
  const int sWi = (int)(Cout * Kd * Kh * Kw);
  const int sWo = (int)(Kd * Kh * Kw);
  const int sWd = (int)(Kh * Kw);
  const int sWh = (int)Kw;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  cudaError_t attr_err = cudaFuncSetAttribute(
      conv_transpose3d_s1_kernel<float>,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));

  conv_transpose3d_s1_kernel<float><<<grid, block, (size_t)smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)Cout,
      (int)Din, (int)Hin, (int)Win,
      (int)Dout, (int)Hout, (int)Wout,
      (int)K, (int)padding,
      (int)td, (int)th, (int)tw,
      (int)halo, pipe,
      sXn, sXc, sXd, sXh,
      sYn, sYc, sYd, sYh,
      sWi, sWo, sWd, sWh
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_s1_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_s1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_s1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    ConvTranspose3d with square input and square kernel, implemented by one custom
    cooperative-tiled CUTE/CUDA kernel in forward().
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(output_padding, int) and output_padding >= 0
        assert isinstance(groups, int) and groups >= 1

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)

        if self.stride != 1:
            raise ValueError("ModelNew custom CUTE kernel supports stride=1 only")
        if self.groups != 1:
            raise ValueError("ModelNew custom CUTE kernel supports groups=1 only")
        if self.output_padding != 0:
            raise ValueError("ModelNew custom CUTE kernel supports output_padding=0 only")

        k = self.kernel_size
        self.weight = nn.Parameter(torch.empty(self.in_channels, self.out_channels, k, k, k))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = cute_conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size ** 3
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_s1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.output_padding),
            int(self.groups),
        )

