  // global-memory staging of input channel ci+1 (input halo + weights)
  // with the compute of channel ci, hiding gmem latency behind FMA work.
  auto stage_channel = [&](int ci, float* sS, float* sW) {
    for (int idx = tid; idx < halo3; idx += Threads) {
      const int hd = idx / halo2;
      const int r  = idx - hd * halo2;
      const int hh = r / halo;
      const int hw = r - hh * halo;
