      const unsigned dst = (unsigned)__cvta_generic_to_shared(sS + idx);
      const int sz = valid ? 4 : 0;  // src-size 0 => zero-fill (padding)
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" :: "r"(dst), "l"(src), "r"(sz));
#else
      sS[idx] = valid ? *src : 0.0f;
#endif
    }
    const int w_items = CoTile * k3;
    for (int idx = tid; idx < w_items; idx += Threads) {
      const int cc = idx / k3;
      const int kk = idx - cc * k3;
      const int kd = kk / k2;
      const int rr = kk - kd * k2;
      const int kh = rr / K;
      const int kw = rr - kh * K;
