    for (int kd = 0; kd < K; ++kd) {
      const int kdr = K - 1 - kd;
      for (int kh = 0; kh < K; ++kh) {
        const int khr = K - 1 - kh;
        for (int kw = 0; kw < K; ++kw) {
          const int kwr = K - 1 - kw;
          const int kk = (kd * K + kh) * K + kw;
          const int tap = kdr * halo2 + khr * halo + kwr;
          float wv[CoTile];
          #pragma unroll
          for (int cc = 0; cc < CoTile; ++cc) {
            wv[cc] = sW[cc * k3 + kk];
          }
          float xvv[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xvv[i] = sS[off[i] + tap];
