            }
          }
        }
      }
    }
  };
  if (pipe) {
    // Prologue: asynchronously stage channel 0 into buffer 0.
    stage_channel(0, sS_buf0, sW_buf0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;\n" ::);
