    for (int ci = 0; ci < Cin; ++ci) {
      // Prefetch channel ci+1 into the alternate buffer while computing ci.
      if (ci + 1 < Cin) {
        stage_channel(ci + 1, ((ci + 1) & 1) ? sS_buf1 : sS_buf0,
