      compute_tile(sS_buf0, sW_buf0);
      __syncthreads();
    }
  }
  #pragma unroll
  for (int cc = 0; cc < CoTile; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      const int p = tid + i * Threads;
      const int z = p >> 6;
      const int r = p & 63;
      const int y = r >> 3;
      const int x = r & 7;
      const int od = od_base + z;
      const int oh = oh_base + y;
      const int ow = ow_base + x;
      if (od < Dout && oh < Hout && ow < Wout) {
        mY(co, od, oh, ow) = static_cast<T>(acc[cc][i]);
      }
    }
  }
}

